#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> mines(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> mines[i][j];
        }
    }

    vector<vector<char>> freeCell(n, vector<char>(n, 1));
    for (const vector<long long>& p : mines) freeCell[p[0]][p[1]] = 0;
    vector<vector<int>> best(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        int run = 0;
        for (int j = 0; j < n; j++) {
            run = freeCell[i][j] ? run + 1 : 0;
            best[i][j] = run;
        }
        run = 0;
        for (int j = (int)n - 1; j >= 0; j--) {
            run = freeCell[i][j] ? run + 1 : 0;
            best[i][j] = min(best[i][j], run);
        }
    }
    int answer = 0;
    for (int j = 0; j < n; j++) {
        int run = 0;
        for (int i = 0; i < n; i++) {
            run = freeCell[i][j] ? run + 1 : 0;
            best[i][j] = min(best[i][j], run);
        }
        run = 0;
        for (int i = (int)n - 1; i >= 0; i--) {
            run = freeCell[i][j] ? run + 1 : 0;
            best[i][j] = min(best[i][j], run);
            answer = max(answer, best[i][j]);
        }
    }
    cout << answer << "\n";

    return 0;
}

